/**
 * One account of an Integration the owner signed in, under a label.
 */
export type IntegrationConnection = {
  integration: string;
  label: string;
  /**
   * The account's own name at the service, such as its email; an app's name.
   */
  account: string;
  /**
   * What the Connection was granted: a service alone to read and write, or with ":read" to read only.
   */
  services: Array<string>;
  /**
   * The service refused the Connection's refresh token for good, or for an account its password the last time the control plane signed in; connect it again.
   */
  sign_in_required: boolean;
  /**
   * Where the service is, for an Integration of kind account.
   */
  address?: string;
  /**
   * What the service said it runs when the Connection was made, when it said.
   */
  version?: string;
  /**
   * The id of the app the Connection is, for an Integration of kind app, or of the app a user Connection signed in through. Not secret.
   */
  app_id?: string;
  /**
   * For a user Connection, the owner's own sign-in through an app: the label of the app Connection it signs in with. It acts as the owner, so only the owner's token and a Bot given it, on the owner's own turn, may use it.
   */
  app?: string;
  /**
   * The role the Connection is, for an Integration of kind role (AWS); account is its AWS account.
   */
  role_arn?: string;
  /**
   * The name of the key the role is assumed with, for an Integration of kind role. Not secret.
   */
  key?: string;
  /**
   * Whether the coordinator may use the Connection in chats, and so give it to a Run. Off until the owner turns it on.
   */
  chats: boolean;
  /**
   * The proxy its requests to its service go through (issue #850), such as socks5://127.0.0.1:1055: a service in a private network, reached through a local proxy. Absent when they go direct.
   */
  proxy?: string;
  /**
   * Where its requests are dialed instead of their host's (issue #850), as curl's --resolve: a host or an IP, with a port or not. The Host header and the TLS name stay the host's. A temporary way round a name that does not resolve; absent dials the host.
   */
  dial_address?: string;
  session?: DeviceSession;
  /**
   * The actions the account cannot do at the service, as last read, in the order they are listed. A request for one is refused before it is sent. Empty when it can do all, or nothing was read.
   */
  cannot: Array<ConnectionCannot>;
  /**
   * When what the account can do was last read at the service; absent when never.
   */
  access_checked_at?: string;
  created_at: string;
  updated_at: string;
};

