export type TodoLinkKind = 'url' | 'chat_message' | 'mail' | 'run' | 'pull_request' | 'meeting_line' | 'lark_message' | 'zalo_message' | 'whatsapp_message' | 'zalo_sent' | 'whatsapp_sent' | 'lark_sent' | 'comment';

/**
 * A typed reference, to where an item came from or to what shows it is done.
 */
export type TodoLink = {
  kind: TodoLinkKind;
  /**
   * The URL, or the id of the message, mail, Run, pull request or meeting line; a chat message's seq; a comment's revision.
   */
  ref: string;
  label?: string;
  /**
   * The owner's account the message is in: a message he sent (zalo_sent, whatsapp_sent, lark_sent), or a person's message given as evidence (zalo_message, whatsapp_message, lark_message).
   */
  account?: string;
  /**
   * The chat the message is in, its id at the service; with account only.
   */
  chat?: string;
};

/**
 * owner, written by hand; chat, a Bot in a chat with the owner; routine, a Bot in a Routine's run; lark, zalo and whatsapp, a Bot reading a chat of the owner's own account there; gmail, a Bot reading a thread of his Gmail; meeting, a Bot reading a meeting he recorded.
 */
export type TodoSourceKind = 'owner' | 'chat' | 'routine' | 'lark' | 'zalo' | 'whatsapp' | 'gmail' | 'meeting';

export type TodoSource = {
  kind: TodoSourceKind;
  /**
   * The chat, the Routine's run, the chat's id at Lark, Zalo or WhatsApp, the Gmail thread's id, or the meeting.
   */
  id?: string;
  /**
   * The owner's account the chat or thread is in; zalo, whatsapp and gmail, and lark when given.
   */
  account?: string;
  /**
   * The words it came from.
   */
  quote?: string;
  ref?: TodoLink;
};

/**
 * Why an item a Bot found starts open: asked_directly, someone tagged or messaged the owner and he has not answered; promised, the owner promised it himself; waiting, he waits on a person, given the item: he gave it to them, it was promised to him, or someone took it in his place. The message that shows it is in the item's history (the event's after.waiting_on); giving the item to anyone else clears it.
 */
export type TodoWhyOpen = 'asked_directly' | 'promised' | 'waiting';

export type TodoActorKind = 'owner' | 'bot' | 'system';

export type TodoActor = {
  kind: TodoActorKind;
  /**
   * The Bot's id, or what of the system.
   */
  id?: string;
};

/**
 * The Bot's current attempt, while doing or review.
 */
export type TodoWork = {
  /**
   * The attempt's own id, which the Bot's writes carry.
   */
  attempt: string;
  kind: 'chat' | 'run';
  /**
   * The chat or the Routine's run the attempt works in.
   */
  id: string;
  bot: string;
  started_at: string;
};

export type TodoEvent = {
  id: number;
  at: string;
  /**
   * The revision the change made.
   */
  revision: number;
  actor: TodoActor;
  /**
   * created, edited, state, snoozed, linked_approval or commented: after.text is the comment, and a Bot's comment may carry after.files, paths in the Bot's folder read through the chat after.chat, and after.artifacts, the ids of Artifacts it showed (issue #1207). An owner comment may carry after.attachments (ChatAttachment objects) and after.chat, the chat they were sent to (issue #1245).
   */
  kind: string;
  /**
   * The fields that changed, before.
   */
  before: {
    [key: string]: unknown;
  };
  /**
   * The fields that changed, after. A Bot's created or edited event that put the item in Waiting on others holds waiting_on too: {by, quote, ref}, the person, their words and the message of the item's own source that shows it (a TodoLink).
   */
  after: {
    [key: string]: unknown;
  };
};

export type Todo = {
  id: string;
  /**
   * Starts at 1 and grows with every change; a change carries it.
   */
  revision: number;
  title: string;
  notes: string;
  done_when: string;
  /**
   * The reply a Bot drafted for the owner to send himself.
   */
  draft: string;
  due: TodoDue;
  assignee: TodoAssignee;
  state: TodoState;
  snoozed_until?: string;
  source: TodoSource;
  created_by: TodoActor;
  why_open?: TodoWhyOpen;
  work?: TodoWork;
  /**
   * The pending Approval it waits for, in review.
   */
  approval_id?: string;
  done_by?: TodoAssignee;
  recorded_by?: TodoActor;
  closed_how?: 'hand' | 'bot' | 'ai' | 'time';
  close_reason: string;
  evidence: Array<TodoLink>;
  closed_at?: string;
  duplicate_of?: string;
  /**
   * The item's own chat with the Bot it was given to, where the owner's comments reach it.
   */
  chat_id?: string;
  /**
   * The Bot the item reached its Bot through: the main Bot that passed it to a project Bot, or the project Bot that gave it back to the main Bot. Left out when the owner or the system gave it.
   */
  passed_by?: string;
  /**
   * A proposal nobody touched for three days, left out of the list unless asked for.
   */
  stale: boolean;
  priority: TodoPriority;
  /**
   * Why it has its priority, in a line, as who set it said it.
   */
  priority_reason: string;
  /**
   * The project it is in, a department of the sidebar by its id (issue #1188); left out when none. An item given to a Bot in a department, without a project, takes that department.
   */
  project_id?: string;
  created_at: string;
  updated_at: string;
  /**
   * Its history, the oldest first; GET /inbox/{todo_id} only.
   */
  events?: Array<TodoEvent>;
};

/**
 * 0 no priority, 1 urgent, 2 high, 3 medium, 4 low (Linear's scale).
 */
export type TodoPriority = number;

export type TodoList = {
  data: Array<Todo>;
  /**
   * How many items the filter matches, every page together.
   */
  total: number;
  /**
   * Present when more items follow.
   */
  next_cursor?: string;
};

