export type LarkChannelSettingsWritable = {
  /**
   * The id of the Bot the Channel talks to, which must exist; the main Bot for a new Channel that names none. A chat that is open keeps its Bot; the next one is with the new Bot.
   */
  bot?: string;
  app_id?: string;
  app_secret?: string;
  /**
   * The owner's email in the app's Lark organization, or his open_id.
   */
  owner?: string;
  mode?: LarkChannelMode;
  enabled?: boolean;
  /**
   * Whether a reply in a direct chat ends with a link to the chat in the web client. A new Channel has it when it is the first Channel, the owner's own, unless told otherwise.
   */
  web_link?: boolean;
};

/**
 * An account of a service at an address of its own (address, username, password), an app of a service (app_id, app_secret), or a role of an AWS account (role_arn, key, and access_key_id with secret_access_key when the key is new or replaced).
 */
export type NewAccountConnectionWritable = {
  /**
   * The app's App ID, for an Integration that is an app. Not secret.
   */
  app_id?: string;
  app_secret?: string;
  /**
   * Where the service is, such as https://superset.example.com.
   */
  address?: string;
  /**
   * The proxy the address is reached through, signing in included (issue #850). Absent keeps the one the label has.
   */
  proxy?: string;
  /**
   * Where the address is dialed instead of its host's, as curl's --resolve (issue #850). Absent keeps the one the label has.
   */
  dial_address?: string;
  username?: string;
  password?: string;
  /**
   * The ARN of the role, such as arn:aws:iam::123456789012:role/hypomnema/read.
   */
  role_arn?: string;
  /**
   * The name the key that assumes the role is kept under, such as main.
   */
  key?: string;
  access_key_id?: string;
  secret_access_key?: string;
};

export type NewIntegrationClientWritable = {
  client_id: string;
  client_secret: string;
};

export type NewTokenAccountWritable = {
  /**
   * The kind of subscription: Claude, whose `claude setup-token` gives a token to paste, or OpenCode Go (issue #854) or OpenCode Zen (issue #965), whose Console API key is the account.
   */
  runtime: 'claude' | 'opencode_go' | 'opencode_zen';
  /**
   * The account's name for the owner; a token names no e-mail.
   */
  label: string;
  /**
   * The token `claude setup-token` prints, or the OpenCode Console key, one line.
   */
  token: string;
};

export type NewAccountImportWritable = {
  /**
   * The kind of subscription; only Claude Code's file is read.
   */
  runtime: 'claude';
  /**
   * The whole `.credentials.json` Claude Code saved, as text.
   */
  credentials: string;
  /**
   * The account's name for the owner; its e-mail when left out. Kept by an account imported again.
   */
  label?: string;
};

